from typing import List
from textkit.normalize_whitespace import normalize_whitespace

def split_sentences(text: str) -> List[str]:
    if not text:
        return []
    normalized = normalize_whitespace(text)
    if not normalized:
        return []
    words = normalized.split(" ")
    abbreviations = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St.", "vs.", "e.g.", "i.e."}
    sentences = []
    current_sentence = []

    for i in range(len(words)):
        word = words[i]
        current_sentence.append(word)

        if i < len(words) - 1:
            next_word = words[i+1]
            is_boundary = False

            # Check terminator run and closing chars
            terminators = ".!?"
            closing = "' \])"

            # Rule: word ends with terminator run, optionally followed by closing chars
            # We look for the last character that is a terminator
            last_term_idx = -1
            for j in range(len(word)-1, -1, -1):
                if word[j] in terminators:
                    last_term_idx = j
                    break
                if word[j] not in closing:
                    break

            if last_term_idx != -1:
                # Check if everything after last_term_idx is in closing_chars
                if all(c in closing for c in word[last_term_idx+1:]):
                    # Check if next word starts with uppercase, digit, or opening quote/bracket
                    if next_word[0].isupper() or next_word[0].isdigit() or next_word[0] in "'( [":
                        # Check for abbreviation/initial exceptions
                        is_abbr = word in abbreviations
                        # Initial: single uppercase letter + '.' (optionally after quote/bracket)
                        stripped = word.lstrip("'( [")
                        is_initial = len(stripped) == 2 and stripped[0].isupper() and stripped[1] == '.'

                        if not (is_abbr or is_initial):
                            is_boundary = True

            if is_boundary:
                sentences.append(" ".join(current_sentence))
                current_sentence = []

    if current_sentence:
        sentences.append(" ".join(current_sentence))
    return sentences
